#include <stdio.h>
#include <string.h>

int main(void) {
    char s[1024];
    if (fgets(s, sizeof(s), stdin)) {
        s[strcspn(s, "\r\n")] = '\0';
        int len = strlen(s);
        int isPal = 1;
        for (int i = 0; i < len / 2; i++) {
            if (s[i] != s[len - 1 - i]) {
                isPal = 0;
                break;
            }
        }
        if (isPal) {
            printf("True\n");
        } else {
            printf("False\n");
        }
    }
    return 0;
}

