#include <iostream>
#include <string>
#include <algorithm>

using namespace std;

int main() {
    string s;
    if (getline(cin, s)) {
        if (!s.empty() && s.back() == '\r') s.pop_back();
        string rev = s;
        reverse(rev.begin(), rev.end());
        if (s == rev) {
            cout << "True" << endl;
        } else {
            cout << "False" << endl;
        }
    }
    return 0;
}

